DELETE FROM `quest_description_conditional` WHERE (`QuestId`=65437 AND `PlayerConditionId`=99433 AND `QuestgiverCreatureId`=0 AND `locale`='enUS') OR (`QuestId`=76114 AND `PlayerConditionId`=923 AND `QuestgiverCreatureId`=0 AND `locale`='enUS');
INSERT INTO `quest_description_conditional` (`QuestId`, `PlayerConditionId`, `QuestgiverCreatureId`, `locale`, `Text`, `OrderIndex`, `VerifiedBuild`) VALUES
(65437, 99433, 0, 'enUS', 'Good to see you again, $p. I hope your exploration of Orgrimmar was fruitful. It is a city built on kinship and courage.\n\nI have just spoken with the Horde Council, and they have accepted the Aspects\' invitation to the Dragon Isles.\n\nPreparations for the journey will begin shortly.\n\nCome, let us speak with the others.', 0, 65940), -- Aspectral Invitation
(76114, 923, 0, 'enUS', '<The glint of a distant object catches your eye. You suddenly remember that you have tender to collect for use at Zen\'shiri Trading Post.>', 0, 65940); -- Report to the Trading Post


